        category, _ = ArtworkCategory.objects.get_or_create(
            slug=category_slug,
            defaults={'name': category_slug.replace('-', ' ').title(), 'sort_order': 99, 'is_active': True},
        )
        artwork.category_id = category.pk
        artwork.save(update_fields=['category'])


